using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class ControllerTests {
  static int checks;static void Check(bool v,string text){checks++;if(!v)throw new Exception(text);}static void Near(double a,double b,string text){Check(Math.Abs(a-b)<1e-7*Math.Max(1,Math.Abs(b)),text+": "+a+" / "+b);}
  static void Wait(Func<bool> f,string text){var watch=System.Diagnostics.Stopwatch.StartNew();while(!f()&&watch.Elapsed.TotalSeconds<120){Application.DoEvents();Thread.Sleep(15);}Check(f(),text);}
  static void Call(object target,string name,params object[] args){target.GetType().GetMethod(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(target,args);}
  static T Result<T>(Task<T> t){Wait(()=>t.IsCompleted,"async viewport completed");return t.GetAwaiter().GetResult();}
  static void Finish(Task t){Wait(()=>t.IsCompleted,"preview saved");t.GetAwaiter().GetResult();}
  static RobotBuild Weightless(RobotDocument d){var b=RobotCad.Build(d);Check(b.Model.Valid,"fixture geometry: "+string.Join(";",b.Model.Errors));foreach(var e in b.Entries.Values)e.MassOverride=0;return b;}
  public static int Run(string folder){Directory.CreateDirectory(folder);var report=new StringBuilder();var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};
   var d=new RobotDocument();var a=d.Add(null);a.EndX=100;a.Mode=RobotJointMode.Вращение_Y;var b=d.Add(a.Id);b.OffsetX=500;b.EndX=0;b.EndZ=20;b.Payload=1;var model=Weightless(d);var exact=RobotSolver.Solve(model).Joints.First();Near(exact.Required,8.829,"500mm child offset gives 8.829 Nm");var bound=BodyLoadEnvelope.Calculate(d,a,model);Check(bound.MomentNmm>=exact.Required*1000,"offset moment bounded without current_required");double before=bound.MomentNmm;a.OffsetX=900;model=Weightless(d);Near(BodyLoadEnvelope.Calculate(d,a,model).MomentNmm,before,"own root translation is not added to lever");
   a.OffsetX=0;model=Weightless(d);var entry=model.Entries.Values.First(e=>e.OwnerId==a.Id&&!e.Guide);entry.MassOverride=2;entry.Local=RobotMath.Translation(1100,0,0)*entry.Local;bound=BodyLoadEnvelope.Calculate(d,a,model);Check(bound.MomentNmm>30000,"shifted actual COM enters load envelope");
   for(int i=0;i<40;i++){a.Position=-90+i*4;b.Position=90-i*3;model.Current=RobotKinematics.Evaluate(d,0,false);var need=RobotSolver.Solve(model).Joints.First().Required*1000;Check(bound.MomentNmm+1e-6>=need,"bound includes COM/offset pose "+i);}
   var linear=new RobotDocument();var l=linear.Add(null);l.Mode=RobotJointMode.Линейный_Z;l.Minimum=0;l.Maximum=100;bool blocked=false;try{ProceduralBodySpec.Build(linear,l,new ProceduralBodySettings());}catch(Exception ex){blocked=ex.Message.Contains("линейного");}Check(blocked,"linear template rejected before treating N as Nm");
   report.AppendLine("PASS load envelopes: offsets, own-origin invariance, actual COM, 40 poses, early linear block.");
   using(var f=new RobotDesignerForm()){f.StartPosition=FormStartPosition.Manual;f.Location=new System.Drawing.Point(-20000,-20000);f.Show();Application.DoEvents();f.SetDocument(RobotDocument.Example());Wait(()=>f.Scene.Ready&&f.WebScene.Ready,"both native viewports ready");f.OpenJointControllers();Wait(()=>f.ControllerCount==3,"three joint controller rows");var j=f.Document.Joints[0];var child=f.Document.Joints.Last();int builds=f.Scene.MeshBuildCount;var geometry=f.Build;double angle=j.Position,length=j.Length;var end=f.Build.Current[child.Id].Tip;
    f.JogJoint(j.Id,7.5);Near(j.Position,angle+7.5,"jog updates coordinate");Check((f.Build.Current[child.Id].Tip-end).Length>1,"descendants follow articulation");Near(j.Length,length,"controller preserves link dimensions");Check(ReferenceEquals(geometry,f.Build)&&f.Scene.MeshBuildCount==builds,"no CAD/mesh rebuild on pose");Near(f.Analysis.Joints[0].Required,RobotSolver.Solve(f.Build).Joints[0].Required,"live load matches pose");Call(f,"Undo");j=f.Document.Joints[0];Near(j.Position,angle,"single undo restores jog");Call(f,"Redo");j=f.Document.Joints[0];Near(j.Position,angle+7.5,"redo restores jog");
    var second=f.Document.Joints[1];f.JogJoint(second.Id,3);var tree=(TreeView)typeof(RobotDesignerForm).GetField("tree",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(f);Check((string)tree.SelectedNode.Tag=="j|"+second.Id,"jog selects the matching tree joint");Call(f,"Undo");j=f.Document.Joints[0];
    var visible=RobotKinematics.Evaluate(f.Document,.8,true);typeof(RobotDesignerForm).GetField("phase",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(f,.8);typeof(RobotDesignerForm).GetField("playing",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(f,true);f.JogJoint(j.Id,1);Near(j.Position,Math.Max(j.Minimum,Math.Min(j.Maximum,visible[j.Id].Value+1)),"jog starts at animated visible angle");foreach(var item in f.Document.Joints.Skip(1))Near(item.Position,visible[item.Id].Value,"other animated joints freeze without jumping");Call(f,"Undo");j=f.Document.Joints[0];
    bool finite=false;try{f.UpdateJointController(j.Id,double.NaN,true);}catch{finite=true;}Check(finite,"nonfinite controller input rejected");
    f.UpdateJointController(j.Id,20,false);f.UpdateJointController(j.Id,30,true);Call(f,"Undo");j=f.Document.Joints[0];Near(j.Position,angle+7.5,"one undo restores grouped drag");f.UpdateJointController(j.Id,99999,true);Near(j.Position,j.Maximum,"upper limit enforced");f.UpdateJointController(j.Id,-99999,true);Near(j.Position,j.Minimum,"lower limit enforced");
    f.ResetJointPose();Check(f.Document.Joints.All(x=>Math.Abs(x.Position-Math.Max(x.Minimum,Math.Min(x.Maximum,0)))<1e-8),"all-zero pose clamps to per-joint limits");
    Wait(()=>Result(f.WebScene.Inspect()).Contains("jointController"),"articulation gizmo exposed");var inspect=Result(f.WebScene.Inspect());Check(inspect.Contains("rotate")&&inspect.Contains("true"),"rotational gizmo mode available");
    j=f.Document.Joints[0];double saved=j.Position;string id=j.Id;var message="window.chrome.webview.postMessage({type:'jointBegin',id:'"+id+"'});window.chrome.webview.postMessage({type:'jointPose',id:'"+id+"',value:12});window.chrome.webview.postMessage({type:'jointEnd',id:'"+id+"'});";Result(f.WebScene.TestScript(message));Wait(()=>Math.Abs(f.Document.Find(id).Position-12)<1e-8,"real WebView joint message moves model");Call(f,"Undo");Near(f.Document.Find(id).Position,saved,"web drag one undo");
    Result(f.WebScene.TestScript("window.chrome.webview.postMessage({type:'jointBegin',id:'"+id+"'});window.chrome.webview.postMessage({type:'jointPose',id:'"+id+"',value:18});window.chrome.webview.postMessage({type:'jointCancel',id:'"+id+"'});"));Wait(()=>Math.Abs(f.Document.Find(id).Position-saved)<1e-8,"cancel restores pose");
    f.SetDocument(linear);f.OpenJointControllers();Wait(()=>f.ControllerCount==1,"linear controller row");f.JogJoint(l.Id,15);Near(f.Document.Find(l.Id).Position,15,"linear slider units mm");Wait(()=>Result(f.WebScene.Inspect()).Contains("translate"),"linear gizmo arrow mode");
    string native=Path.Combine(Path.GetDirectoryName(folder),"connected","SixAxis_Connected.robot.json");f.SetDocument(File.Exists(native)?RobotDocument.Parse(File.ReadAllText(native)):RobotDocument.DefaultReference());f.OpenJointControllers();Wait(()=>f.Scene.Ready&&f.WebScene.Ready&&f.ControllerCount==6,"six-axis loaded controller rows");Wait(()=>!f.ProceduralBusy,"reference generation settles");Finish(f.WebScene.SavePreview(Path.Combine(folder,"controllers.png")));f.ApproveTestClose();f.Close();
   }
   report.AppendLine("PASS controllers: all joints, limits, no rebuild, descendant motion, loads, grouped undo/redo, WebView messages, cancellation and linear units.");report.AppendLine("PASS "+checks+" controller/load assertions.");File.WriteAllText(Path.Combine(folder,"controller-results.txt"),report.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"controller-error.txt"),report+Environment.NewLine+ex,Encoding.UTF8);return 1;}finally{AppSettings.Current=old;}}
 }
 public sealed partial class RobotDesignerForm {internal int ControllerCount{get{return jointControllers.Count;}}}
}
